async function saveAssignmentEdits(s){const result=assignmentsFromForm('inventory-edit-rack-assignments');if(!result.selectedRackIds.length){toast('El inventario debe conservar al menos un rack.','warning');return;}if(result.missing.length){showMissing(result.missing,'inventory-edit-unassigned-warning');toast('No puedes dejar racks incluidos sin responsable.','warning');return;}validateCounterAssignments(result.byUser);const previous=s.assignments||[],next=buildAssignments(result.byUser,previous),at=new Date().toISOString();for(const old of previous){const oldLocked=(s.lines||[]).some(l=>l.assignmentId===old.id);if(oldLocked&&!next.some(n=>n.id===old.id))throw new Error(`No se puede eliminar la tarea de ${userName(old.userId)} porque ya tiene conteos.`);}await store.commit(d=>{const target=(d.planning?.inventorySessions||[]).find(x=>x.id===s.id);if(!target||target.status!=='EN_CONTEO')throw new Error('El inventario ya no permite cambiar asignaciones.');target.assignments=next;target.rackIds=result.selectedRackIds;target.updatedAt=at;target.assignmentsUpdatedAt=at;target.assignmentsUpdatedBy=currentUser().id;},`Asignaciones de ${s.number} actualizadas`,{operations:['inventoryManage']});document.querySelector('#inventory-edit-assignments-dialog')?.close();renderInventories(document.querySelector('#app'));}
