function refreshRackSelection(rootId){const root=document.querySelector(`#${rootId}`);if(!root)return;for(const inc of root.querySelectorAll('.inventory-rack-include')){const card=inc.closest('.inventory-rack-assignment'),sel=card?.querySelector('.inventory-rack-user'),included=inc.checked;card?.classList.toggle('is-included',included);card?.classList.toggle('is-excluded',!included);if(sel&&!card?.classList.contains('is-locked'))sel.disabled=!included;const map=document.querySelector(`.inventory-mini-rack[data-map-rack="${CSS.escape(inc.dataset.rack)}"]`);map?.classList.toggle('is-selected',included);map?.classList.toggle('is-excluded',!included);}}
