function wireZoneBulk(rootId){document.querySelectorAll(`#${rootId} .inventory-zone-same`).forEach(btn=>btn.addEventListener('click',()=>{const sector=btn.dataset.sector,zoneUser=document.querySelector(`#${rootId} .inventory-zone-user[data-sector="${CSS.escape(sector)}"]`)?.value||'',selects=[...document.querySelectorAll(`#${rootId} .inventory-rack-user[data-sector="${CSS.escape(sector)}"]`)].filter(x=>!x.disabled);if(!zoneUser){toast('Selecciona primero la persona responsable de esa zona.','warning');return;}for(const s of selects)s.value=zoneUser;}));document.querySelectorAll(`#${rootId} .inventory-zone-toggle`).forEach(btn=>btn.addEventListener('click',()=>{const checks=[...document.querySelectorAll(`#${rootId} .inventory-rack-include[data-sector="${CSS.escape(btn.dataset.sector)}"]`)].filter(x=>!x.disabled),all=checks.length&&checks.every(x=>x.checked);checks.forEach(x=>x.checked=!all);refreshRackSelection(rootId);}));document.querySelectorAll(`#${rootId} .inventory-rack-include`).forEach(x=>x.addEventListener('change',()=>refreshRackSelection(rootId)));}
function wireCreateScope(){const scope=document.querySelector('#inventory-scope');if(!scope)return;scope.addEventListener('change',()=>{const partial=scope.value==='SELECTED_RACKS',root=document.querySelector('#inventory-rack-assignments');if(!root)return;for(const inc of root.querySelectorAll('.inventory-rack-include')){inc.disabled=!partial;if(!partial)inc.checked=true;else inc.checked=false;}for(const sel of root.querySelectorAll('.inventory-rack-user'))if(partial)sel.value='';for(const b of root.querySelectorAll('.inventory-zone-toggle'))b.hidden=!partial;const sh=document.querySelector('#inventory-scope-help'),ah=document.querySelector('#inventory-assignment-help-text');if(sh)sh.textContent=partial?'Selecciona únicamente los racks o zonas que quieres contar.':'Se incluirán todos los racks activos del centro.';if(ah)ah.textContent=partial?'Solo los racks seleccionados deben tener responsable. Los demás quedan fuera de esta sesión.':'Cada rack activo debe quedar con un responsable. Puedes usar una sola persona o repartir la bodega entre varias.';refreshRackSelection('inventory-rack-assignments');});}
function wireDetail(s){document.querySelector('#inventory-back')?.addEventListener('click',()=>{currentSessionId='';inventoryManagerDetailTarget='';renderInventories(document.querySelector('#app'));});const product=document.querySelector('#inventory-product-code'),location=document.querySelector('#inventory-location-code');product?.addEventListener('input',updateResolved);location?.addEventListener('input',updateResolved);enlazarBotonEscaner('inventory-product-scan','inventory-product-code',{titulo:'Escanear producto',ayuda:'Apunta al código del producto',onDetectar:updateResolved,onError:m=>toast(m,'warning')});enlazarBotonEscaner('inventory-location-scan','inventory-location-code',{titulo:'Escanear ubicación o pallet',ayuda:'Apunta al código físico de ubicación o pallet',onDetectar:updateResolved,onError:m=>toast(m,'warning')});document.querySelector('#inventory-save-line')?.addEventListener('click',()=>saveLine(s).catch(e=>toast(e.message,'warning')));document.querySelector('#inventory-count-qty')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();document.querySelector('#inventory-save-line')?.click();}});document.querySelectorAll('.inventory-rack-reviewed').forEach(b=>b.addEventListener('click',()=>toggleRackReviewed(s,b.dataset.rack).catch(e=>toast(e.message,'warning'))));document.querySelector('#inventory-submit-count')?.addEventListener('click',()=>submitMyCount(s).catch(e=>toast(e.message,'warning')));document.querySelector('#inventory-close-session')?.addEventListener('click',()=>closeInventory(s).catch(e=>toast(e.message,'warning')));document.querySelector('#inventory-delete-session')?.addEventListener('click',()=>deleteInventorySession(s).catch(e=>toast(e.message,'warning')));document.querySelector('#inventory-edit-assignments')?.addEventListener('click',()=>document.querySelector('#inventory-edit-assignments-dialog')?.showModal());for(const id of ['inventory-edit-close','inventory-edit-cancel'])document.querySelector(`#${id}`)?.addEventListener('click',()=>document.querySelector('#inventory-edit-assignments-dialog')?.close());document.querySelector('#inventory-edit-save')?.addEventListener('click',()=>saveAssignmentEdits(s).catch(e=>toast(e.message,'warning')));wireZoneBulk('inventory-edit-rack-assignments');wireMapReference('inventory-edit-rack-assignments');document.querySelectorAll('.inventory-manager-toggle').forEach(b=>b.addEventListener('click',()=>{inventoryManagerDetailTarget=inventoryManagerDetailTarget===b.dataset.target?'':b.dataset.target;renderInventories(document.querySelector('#app'));setTimeout(()=>{if(inventoryManagerDetailTarget)document.getElementById(inventoryManagerDetailTarget)?.scrollIntoView({behavior:'smooth',block:'nearest'});},40);}));document.querySelectorAll('.inventory-manager-export-count').forEach(b=>b.addEventListener('click',()=>{const a=(s.assignments||[]).find(x=>String(x.id)===String(b.dataset.assignment));if(a)exportOperatorCountExcel(s,a).catch(e=>toast(e.message||'No fue posible generar el Excel del operario.','warning'));}));document.querySelectorAll('.inventory-manager-export-stock').forEach(b=>b.addEventListener('click',()=>{const a=(s.assignments||[]).find(x=>String(x.id)===String(b.dataset.assignment));if(a)exportRackContentExcel(s,a).catch(e=>toast(e.message||'No fue posible generar el Excel de racks.','warning'));}));if((perms().manage||perms().review)&&['EN_REVISION','CERRADA','CONCILIADA'].includes(s.status))wireInventoryResults(s);}
function wireList(){const dialog=document.querySelector('#inventory-create-dialog');document.querySelector('#inventory-create')?.addEventListener('click',()=>{dialog?.classList.remove('inventory-dialog-maximized');const size=document.querySelector('#inventory-create-size');if(size){size.textContent='⛶';size.title='Ampliar ventana';size.setAttribute('aria-label','Ampliar ventana');}dialog?.showModal();});document.querySelector('#inventory-create-size')?.addEventListener('click',()=>{if(!dialog)return;const maximized=dialog.classList.toggle('inventory-dialog-maximized'),size=document.querySelector('#inventory-create-size');if(size){size.textContent=maximized?'❐':'⛶';size.title=maximized?'Restaurar ventana':'Ampliar ventana';size.setAttribute('aria-label',size.title);}});for(const id of ['inventory-create-close','inventory-create-cancel'])document.querySelector(`#${id}`)?.addEventListener('click',()=>dialog?.close());document.querySelector('#inventory-create-save')?.addEventListener('click',()=>createSession().catch(e=>toast(e.message,'warning')));document.querySelectorAll('.open-inventory-session').forEach(b=>b.addEventListener('click',()=>{currentSessionId=b.dataset.id;inventoryManagerDetailTarget='';renderInventories(document.querySelector('#app'));}));wireZoneBulk('inventory-rack-assignments');wireMapReference('inventory-rack-assignments');wireCreateScope();}

export function renderInventories(root){const p=perms(),assigned=sessions().some(s=>s.siteId===siteId()&&!!taskForUser(s,currentUser().id)),allowed=p.count||p.manage||p.review||assigned;if(!allowed){root.innerHTML=shell('Inventarios',accessDenied(),'inventarios');wireShell();return;}const list=visibleSessions(),current=currentSessionId?list.find(s=>s.id===currentSessionId):null;if(current){root.innerHTML=shell('Inventarios',sessionDetail(current),'inventarios');wireShell();wireDetail(current);startSilentRefresh('inventarios-live','#/inventarios',()=>renderInventories(root),{interval:5000});return;}root.innerHTML=shell('Inventarios',`<section class="panel inventory-home"><div class="panel-head"><div><span class="eyebrow">CONTEO FÍSICO · ${esc(siteName(siteId()))}</span><h2>Inventarios</h2><small>Crea y asigna · El operador ejecuta.</small></div>${p.manage?'<button id="inventory-create" class="primary" type="button">+ Nueva sesión</button>':''}</div>${metricsHtml(list)}<div class="inventory-safety"><b>✓ Flujo controlado</b><span>Cada rack incluido en la sesión debe tener responsable. Puedes inventariar toda la bodega o únicamente racks y zonas seleccionados.</span></div><div class="inventory-session-list">${list.length?list.map(sessionCard).join(''):empty('No hay sesiones de inventario','Cuando el jefe cree y asigne una sesión aparecerá aquí.')}</div></section>${p.manage?createDialog():''}`,'inventarios');wireShell();wireList();startSilentRefresh('inventarios-live','#/inventarios',()=>renderInventories(root),{interval:5000});}
